"""Contracts to C# records (design spec 7.3), generated by code, never by a model.

The XSD, WSDL and JSON Schema walk is the neutral contract model (``engine.stacks.contracts``);
this module renders that model as C#: records become ``public sealed record`` types with ``init``
properties (``required`` for required elements), ``[JsonPropertyName("camelCase")]`` and
``[TibcoPath("/Root/field")]`` for lineage. Enumerations become C# enums, repeating elements
``IReadOnlyList<T>``, optional elements nullable types. ``xsd_to_records`` takes an XSD (or the
schemas embedded in a WSDL), ``json_schema_to_records`` JSON Schema and Swagger 2.0
``definitions`` (the BW6 service descriptors).

The ``TibcoPathAttribute`` class itself is emitted once by the solution generator (Task 14) into
``Contracts/TibcoPathAttribute.cs`` in the same namespace; here only its usage is emitted.
"""
from __future__ import annotations

from dataclasses import dataclass

from engine.ir.models import Contract
from engine.stacks import contracts as neutral
from engine.stacks.contracts import (
    ContractModel,
    ContractPlan,
    contract_module,
    pascal,
    record_names,
)
from engine.stacks.dotnet.naming import DotnetNaming

__all__ = ["ContractPlan", "contract_file", "contract_module", "contract_namespace", "csharp_type",
           "json_schema_to_records", "pascal", "plan_contracts", "record_names", "render", "to_records",
           "xsd_to_records"]

_ident = neutral.ident
_NAMING = DotnetNaming()

# Neutral scalars that are spelled differently in C#; the others (string, int, long, ulong,
# decimal, double, float, bool) and record or enum names are the C# name already.
_CS_TYPES: dict[str, str] = {"date": "DateOnly", "datetime": "DateTimeOffset", "time": "TimeOnly",
                             "bytes": "byte[]", "any": "object"}


def csharp_type(type_ref: str) -> str:
    """The C# type of a neutral ``type_ref`` (without list or nullable decoration)."""
    return _CS_TYPES.get(type_ref, type_ref)


def _xml_escape(text: str) -> str:
    return " ".join(text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").split())


def _cs_string(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"')


# ------------------------------------------------------------------- renderer
def render(model: ContractModel, namespace: str, source: str) -> str:
    """The C# file of ``model`` in ``namespace``; ``source`` (the contract id) is named in comments."""
    lines = [
        "// <auto-generated>",
        f"//   Generated by ExiQO Migrate from {source}. Do not edit by hand.",
        "// </auto-generated>",
        "#nullable enable",
        "",
        "using System;",
        "using System.Collections.Generic;",
        "using System.Text.Json.Serialization;",
        "",
        f"namespace {namespace};",
    ]
    for rec in model.records.values():
        lines.append("")
        summary = f"Contract {rec.name} from {source}." + (f" {rec.doc}" if rec.doc else "")
        lines.append(f"/// <summary>{_xml_escape(summary)}</summary>")
        lines.append(f"public sealed record {rec.name}")
        lines.append("{")
        for i, p in enumerate(rec.props):
            if i:
                lines.append("")
            cs_type = csharp_type(p.type_ref)
            if p.repeated:
                cs_type = f"IReadOnlyList<{cs_type}>"
            if not p.required:
                cs_type += "?"
            lines.append(f'    [JsonPropertyName("{_cs_string(p.json_name)}")]')
            lines.append(f'    [TibcoPath("{_cs_string(p.tibco_path)}")]')
            req = "required " if p.required else ""
            lines.append(f"    public {req}{cs_type} {p.name} {{ get; init; }}")
        lines.append("}")
    for en in model.enums.values():
        lines.append("")
        lines.append(f"/// <summary>Enumeration {en.name} from {_xml_escape(source)}.</summary>")
        lines.append(f"[JsonConverter(typeof(JsonStringEnumConverter<{en.name}>))]")
        lines.append(f"public enum {en.name}")
        lines.append("{")
        used: set[str] = set()
        for v in en.values:
            member = _ident(v) if v else "Empty"
            cand, n = member, 2
            while cand in used:
                cand, n = f"{member}{n}", n + 1
            used.add(cand)
            lines.append(f'    [JsonStringEnumMemberName("{_cs_string(v)}")]')
            lines.append(f"    {cand},")
        lines.append("}")
    return "\n".join(lines) + "\n"


def xsd_to_records(contract: Contract, namespace: str, reserved: frozenset[str] = frozenset()) -> str:
    """C# records and enums for an XSD (or the schemas inside a WSDL) in ``namespace``.

    ``reserved`` are record names other contracts already emit into the same namespace; a clash is
    renamed with a suffix (see ``plan_contracts``).
    """
    return render(neutral.xsd_model(contract, reserved), namespace, contract.id)


def json_schema_to_records(contract: Contract, namespace: str, reserved: frozenset[str] = frozenset()) -> str:
    """C# records and enums for a JSON Schema or Swagger 2.0 document (``definitions``/``$defs``)."""
    return render(neutral.json_model(contract, reserved), namespace, contract.id)


def to_records(contract: Contract, namespace: str, reserved: frozenset[str] = frozenset()) -> str:
    """Dispatch on ``contract.kind``: json to ``json_schema_to_records``, xsd and wsdl to XSD."""
    return render(neutral.contract_model(contract, reserved), namespace, contract.id)


# ------------------------------------------------- C# view for the generator
@dataclass
class _CsProp:
    wire_name: str
    cs_name: str
    cs_type: str  # item type, without list or nullable decoration
    required: bool
    repeated: bool
    path_part: str
    child: str | None


@dataclass
class _CsRecord:
    name: str
    props: list[_CsProp]


class _CsModel:
    """The neutral model with C# type names, as the solution generator reads records."""

    def __init__(self, model: ContractModel) -> None:
        self._model = model
        self.enums = model.enums
        self.records = {
            name: _CsRecord(name, [_CsProp(p.json_name, p.name, csharp_type(p.type_ref), p.required, p.repeated,
                                           p.path_part, p.child) for p in rec.props])
            for name, rec in model.records.items()}

    def names(self) -> list[str]:
        return self._model.names()

    def paths(self) -> dict[str, str]:
        return self._model.lineage()


def _model(contract: Contract, reserved: frozenset[str] = frozenset()) -> _CsModel:
    return _CsModel(neutral.contract_model(contract, reserved))


# ------------------------------------------------------- per-application plan
def contract_namespace(app_name: str, contract: Contract) -> str:
    """``<App>.Core.Contracts.<Module>``; ``TibcoPathAttribute`` in ``<App>.Core.Contracts`` is in scope."""
    return _NAMING.contract_target(app_name, contract_module(contract), neutral.stem(contract))[0]


def contract_file(contract: Contract) -> str:
    """Natural file path in the Core project: ``Contracts/<Module>/<Stem>.cs``."""
    return _NAMING.contract_target("", contract_module(contract), neutral.stem(contract))[1]


def plan_contracts(app_name: str, contracts: list[Contract]) -> dict[str, ContractPlan]:
    """``engine.stacks.contracts.plan_contracts`` with the .NET naming."""
    return neutral.plan_contracts(app_name, contracts, _NAMING)
